"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65685"],{7806(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_repetido","status":422,"titulo":"O fato aparece mais de uma vez entre os pressupostos"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_repetido","requisitos":[],"oQueAconteceu":["A lista `pressupostos` do `conteudo` do modelo, enviada na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), cita o mesmo fato duas ou mais vezes. A compara\xe7\xe3o \xe9 exata, depois de aparados os espa\xe7os nas pontas e normalizado o texto.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.pressupostos[i]`, em que `i` \xe9 a posi\xe7\xe3o de cada repeti\xe7\xe3o depois da primeira. A mensagem cita o c\xf3digo do fato. A confer\xeancia s\xf3 \xe9 feita depois que o conte\xfado foi lido sem recusa de leitura, e num modelo que n\xe3o \xe9 o de inscri\xe7\xe3o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Deixe cada fato uma s\xf3 vez na lista `pressupostos` e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);